 foreach($doc['rosters']??[]as$r){if((string)($r['team']['id']??'')!==$teamId)continue;$formation=(string)($r['formation']??'');if(!in_array($formation,$supported,true))return null;$players=[];$ids=[];$gk=0;$starters=[];foreach($r['roster']??[]as$q)if(($q['starter']??false)===true)$starters[(string)($q['athlete']['id']??'')]=true;
