 $kick=strtotime($m['kickoff']??'');$remote=strtotime($doc['header']['competitions'][0]['date']??'');return $kick&&$remote&&abs($kick-$remote)<61&&($teams['home']??'')===(string)($m['home']['espnId']??'')&&($teams['away']??'')===(string)($m['away']['espnId']??'');
