   $xi[$j]=array_merge($keep($base,$k),['position'=>$r,'roles'=>[$r],'captain'=>false]);}
  ksort($xi);$t['players']=array_values($xi);
  foreach($names as$k=>$n)if(!isset($used[$k])&&!isset($bench[$k])){$sq=$squad[$k]??[];$r=['GK'=>'GK','DF'=>'DEF','MF'=>'MID','FW'=>'ST'][$sq['pos']??'']??'MID';$bench[$k]=array_merge(['id'=>'callup-'.substr(sha1($n),0,10),'shortName'=>$n,'naturalRoles'=>[$r],'availability'=>'not-flagged'],pp_callup_roster_player($k)??[],['name'=>$n,'number'=>!empty($sq['number'])?(int)$sq['number']:null,'position'=>$r,'roles'=>[$r],'calledUp'=>true]);}
  $t['bench']=array_values($bench);
  if(!empty($e['coach'])&&pp_public_name($t['coach']['name']??'')!==pp_public_name($e['coach']))$t['coach']=['name'=>$e['coach'],'source'=>'federation call-up','basis'=>'federation-callup','asOf'=>$now->format(DATE_ATOM)];
  $t['source']['callup']=['window'=>$e['window']??null,'players'=>count($e['players']),'source'=>$e['source']??null,'applied'=>'all-providers'];$snap['teams'][$i]=$t;}
 return $snap;
}
function pp_players_group(string $role):string{return $role==='GK'?'G':(in_array($role,['CB','LB','RB','LWB','RWB','DEF'],true)?'D':(in_array($role,['ST','LW','RW'],true)?'F':'M'));}
function pp_players_recent(array $m,string $side,string $code,array $cfg,DateTimeImmutable $now,?callable $fetcher=null):?array{
 $team=(string)($m[$side]['espnId']??'');if(!preg_match('/^\d{1,12}$/',$team))return null;$root='https://site.api.espn.com/apis/site/v2/sports/soccer/'.$code.'/teams/'.$team;
 $currentDoc=pp_players_json($root.'/roster',$cfg,$now,$fetcher);if((string)($currentDoc['team']['id']??'')!==$team)return null;$current=[];foreach($currentDoc['athletes']??[]as$a){$id=(string)($a['id']??'');$current[$id]=['name'=>trim((string)($a['displayName']??$a['fullName']??'')),'pos'=>(string)($a['position']['abbreviation']??''),'available'=>!in_array(strtolower($a['status']['type']??'active'),['inactive','injured','suspended','out'],true)&&!($a['injured']??false),'dateOfBirth'=>$a['dateOfBirth']??null,'number'=>preg_match('/^\d{1,3}$/',(string)($a['jersey']??''))?(int)$a['jersey']:null,'physical'=>['heightCm'=>isset($a['height'])&&$a['height']>=55&&$a['height']<=90?round($a['height']*2.54,1):null,'weightKg'=>isset($a['weight'])&&$a['weight']>=90&&$a['weight']<=300?round($a['weight']*.45359237,1):null,'source'=>'ESPN roster','verifiedMeasurements'=>true]];}$current=pp_national_callup_apply($current,$team,$m);if(count(array_filter($current,fn($p)=>$p['available']))<11)return null;
 $schedule=pp_players_json($root.'/schedule',$cfg,$now,$fetcher);if((string)($schedule['team']['id']??'')!==$team)return null;$events=[];$cut=min($now->getTimestamp(),strtotime($m['kickoff']??$m['date'])?:0);
 foreach($schedule['events']??[]as$e){$at=strtotime($e['date']??'');$c=$e['competitions'][0]??[];$members=array_map(fn($t)=>(string)($t['team']['id']??$t['id']??''),$c['competitors']??[]);if($at&&$at+7200<$cut&&$cut-$at<45*86400&&($c['status']['type']['completed']??false)&&in_array($team,$members,true))$events[]=$e;}
 usort($events,fn($a,$b)=>strcmp($b['date'],$a['date']));foreach(array_slice($events,0,3)as$e){$id=(string)($e['id']??'');if(!preg_match('/^\d{1,15}$/',$id))continue;$doc=pp_players_json('https://site.api.espn.com/apis/site/v2/sports/soccer/'.$code.'/summary?event='.$id,$cfg,$now,$fetcher);$c=$doc['header']['competitions'][0]??[];if((string)($doc['header']['id']??'')!==$id||!($c['status']['type']['completed']??false))continue;$lineup=pp_players_extract($doc,$team,$now,'estimated-from-recent-start',$current);if($lineup){$lineup=pp_national_callup_enrich($lineup,$current,$team,$m,$now);$lineup['coach']=pp_players_coach($currentDoc['coach']??$currentDoc['coaches']??$currentDoc['team']['coach']??$currentDoc['team']['coaches']??[])??$lineup['coach'];if(!empty($lineup['coach']))$lineup['coach']+=['asOf'=>$currentDoc['_wosSource']['asOf']??$now->format(DATE_ATOM),'basis'=>'current-club','url'=>$root.'/roster'];$lineup['source']['basisDate']=$e['date'];return $lineup;}}
 return null;
}
function pp_players_team_codes(array $m,string $side,array $cfg):array{
 $codes=[pp_players_code($m)];$team=(string)($m[$side]['espnId']??'');
 // European fixtures can use the team's domestic recent XI, too.
 $state=pp_read($cfg['storage_dir'].'/state.json');
